138	<script>
139	  import router from '@system.router'
140	  import storage from '@system.storage'
141	  import file from '@system.file'
142	  import { getSearchEngine } from '../../SearchEngine/SearchEngine.js'
143	
144	  export default {
145	    private: {
146	      bgColor: '#000000',
147	      loadingText: '正在加载...',
148	      progressPercent: 0,
149	      showProgress: false,
150	      showExitBtn: false,
151	      dotIndex: 0,
152	      timer: null,
153	      dotTimer: null,
154	      monitorTimer: null,
155	      dot1Color: '#333333',
156	      dot2Color: '#333333',
157	      dot3Color: '#333333',
158	      engine: null,
159	      isScreenOff: false,
160	      loadStartTime: 0,
161	      loadRetryCount: 0,
162	      debugMsg: '',
163	      hasNavigated: false
164	    },
165	
166	    onInit() {
167	  global.addRuntimeLog('应用启动', 'info')
168	  storage.get({
169	    key: 'quick_launch',
170	    success: (data) => {
171	      global.quickLaunch = data === 'true'
172	      global.addRuntimeLog('快速启动: ' + (global.quickLaunch ? '开启' : '关闭'), 'info')
173	    },
174	    fail: () => {
175	      global.quickLaunch = false
176	    }
177	  })
178	  // settings.ux - onInit 中
179	storage.get({ 
180	  key: 'auto_search', 
181	  success: (d) => { 
182	    this.autoSearch = d === 'true'
183	    global.autoSearch = this.autoSearch
184	  },
185	  fail: () => { 
186	    this.autoSearch = false
187	    global.autoSearch = false
188	  }
189	})
190	  // ========== 第2步：启动引擎加载 ==========
191	  this.startEngineLoad()
192	  
193	  // ========== 第3步：加载名言数据 ==========
194	  file.readText({
195	    uri: '/common/quotes.txt',
196	    success: (data) => {
197	      const lines = data.text.split('\n')
198	      global.quotes = lines
199	        .filter(line => line.includes('|'))
200	        .map(line => {
201	          const parts = line.split('|')
202	          return { text: parts[0], author: parts[1] }
203	        })
204	      global.addRuntimeLog('名言数据加载完成', 'success')
205	    },
206	    fail: () => {
207	      global.quotes = [{ text: '以史为镜，可以知兴替', author: '李世民' }]
208	      global.addRuntimeLog('名言数据加载失败，使用默认', 'warn')
209	    }
210	  })
211	},
212	
213	    onDestroy() {
214	      if (this.timer) clearTimeout(this.timer)
215	      if (this.dotTimer) clearInterval(this.dotTimer)
216	      if (this.monitorTimer) clearInterval(this.monitorTimer)
217	    },
218	    
219	    onHide() {
220	      if (this.progressPercent > 0 && this.progressPercent < 100 && !this.showExitBtn) {
221	        this.isScreenOff = true
222	      }
223	    },
224	    
225	    onShow() {
226	      if (this.progressPercent === 100 && !this.hasNavigated && !this.showExitBtn) {
227	        this.finish()
228	        return
229	      }
230	      if (this.isScreenOff && this.progressPercent > 0 && this.progressPercent < 100 && !this.showExitBtn) {
231	        this.isScreenOff = false
232	        setTimeout(() => {
233	          if (this.progressPercent > 0 && this.progressPercent < 100) {
234	            this.retryEngineLoad()
235	          }
236	        }, 1000)
237	      } else {
238	        this.isScreenOff = false
239	      }
240	    },
241	
242	    async startEngineLoad() {
243	      global.addRuntimeLog('启动页开始加载', 'info')
244	      this.hasNavigated = false
245	      this.startDots()
246	      this.loadStartTime = Date.now()
247	      this.loadRetryCount = 0
248	      this.showExitBtn = false
249	      
250	      this.loadingText = '1/4 读取设置...'
251	      this.showProgress = false
252	      await this.loadSettingsAsync()
253	      global.addRuntimeLog('设置读取完成', 'info')
254	      this.loadingText = '2/4 加载索引数据...'
255	      this.showProgress = true
256	      this.progressPercent = 10
257	      this.engine = getSearchEngine()
258	      
259	      const self = this
260	      var isQuickLaunch = global.quickLaunch || false
261	  if (isQuickLaunch) {
262	    global.addRuntimeLog('快速启动模式', 'info')
263	    this.loadingText = '快速启动中...'
264	    this.showProgress = true
265	    this.progressPercent = 50
266	    
267	    await this.engine.initLight('/common/')
268	    this.mountToGlobal()
269	    this.finish()
270	    return  // 快速启动直接返回，不继续执行正常加载
271	  }
272	      // 超时保护（70秒）
273	      var timeoutId = setTimeout(function() {
274	        if (self.loadingText !== '错误：数据加载失败' && 
275	            self.loadingText !== '错误：加载超时，请重启应用' &&
276	            !self.showExitBtn) {
277	          self.loadingText = '错误：加载超时\n点击下方退出应用'
278	          self.showProgress = false
279	          self.progressPercent = 0
280	          self.showExitBtn = true
281	          if (self.dotTimer) clearInterval(self.dotTimer)
282	        }
283	      }, 70000)
284	      
285	      try {
286	        const success = await this.engine.init('/common/', (percent, message) => {
287	  // 强制更新进度
288	  this.progressPercent = percent
289	  this.loadingText = message || (percent + '% 加载索引...')
290	  // 强制刷新界面（Vela 中可能需要）
291	  if (percent % 10 === 0 || percent === 100) {
292	    this.debugMsg = '进度: ' + percent + '%'
293	  }
294	  if (percent === 100) {
295	    this.debugMsg = '加载完成，准备跳转...'
296	  }
297	})
298	        
299	        clearTimeout(timeoutId)
300	        
301	        if (!success) {
302	          this.loadingText = '错误：数据加载失败'
303	          this.showProgress = false
304	          this.progressPercent = 0
305	          this.showExitBtn = true
306	          if (this.dotTimer) clearInterval(this.dotTimer)
307	          return
308	        }
309	        
310	        this.loadingText = '3/4 准备数据接口...'
311	        this.progressPercent = 90
312	        this.mountToGlobal()
313	        
314	        this.loadingText = '4/4 完成，进入应用'
315	        this.progressPercent = 100
316	        
317	        // 延迟跳转，确保界面更新
318	        this.timer = setTimeout(() => {
319	          this.finish()
320	        }, 500)
321	        
322	      } catch (e) {
323	        clearTimeout(timeoutId)
324	        this.loadingText = '错误：引擎初始化异常'
325	        this.showProgress = false
326	        this.progressPercent = 0
327	        this.showExitBtn = true
328	        if (this.dotTimer) clearInterval(this.dotTimer)
329	        console.error('[splash] 引擎初始化异常:', e)
330	      }
331	    },
332	    
333	    retryEngineLoad() {
334	      this.loadRetryCount++
335	      if (this.loadRetryCount > 3) {
336	        this.loadingText = '错误：多次重试失败\n请退出重试'
337	        this.showExitBtn = true
338	        if (this.dotTimer) clearInterval(this.dotTimer)
339	        return
340	      }
341	      
342	      this.loadingText = '重新加载中... (' + this.loadRetryCount + '/3)'
343	      this.progressPercent = 10
344	      
345	      const self = this
346	      
347	      setTimeout(async function() {
348	        try {
349	          self.engine = getSearchEngine()
350	          const success = await self.engine.init('/common/', function(percent, message) {
351	            self.progressPercent = percent
352	            self.loadingText = message || (percent + '% 加载索引...')
353	          })
354	          
355	          if (success) {
356	            self.loadingText = '3/4 准备数据接口...'
357	            self.progressPercent = 90
358	            self.mountToGlobal()
359	            self.loadingText = '4/4 完成，进入应用'
360	            self.progressPercent = 100
361	            self.timer = setTimeout(() => { self.finish() }, 500)
362	          } else {
363	            self.loadingText = '错误：重试加载失败'
364	            self.showExitBtn = true
365	            if (self.dotTimer) clearInterval(self.dotTimer)
366	          }
367	        } catch (e) {
